CREATE FUNCTION public.pipeline_recalculate(aid uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a assessment_attempts;b assessment_batteries;i jsonb;rec jsonb;pair jsonb;v numeric;method text;sc jsonb:='{}';itemsc jsonb:='{}';ksc jsonb:='{}';key text;cnt integer;done boolean:=true;w jsonb;total numeric:=0;weight numeric;BEGIN PERFORM pg_advisory_xact_lock(811112026);SELECT * INTO a FROM assessment_attempts WHERE id=aid FOR UPDATE;IF a.status NOT IN ('submitted','scored') THEN RAISE EXCEPTION 'Submit first';END IF;SELECT * INTO b FROM assessment_batteries WHERE id=a.battery_id;FOR i IN SELECT value FROM jsonb_array_elements(b.payload->'items') WHERE value->>'status'='approved' AND NOT (value->>'practice')::boolean LOOP v:=NULL;method:=i->>'method';IF method IN ('work_sample','interview') THEN rec:=a.reconciliations->(i->>'id');IF rec IS NOT NULL THEN SELECT avg((value::text::numeric-1)*25) INTO v FROM jsonb_array_elements(rec->'ratings');ELSE SELECT jsonb_agg(value) INTO pair FROM (SELECT value FROM jsonb_array_elements(a.raters) WHERE value->>'item_id'=i->>'id' ORDER BY value->>'user_id' LIMIT 2) p;IF jsonb_array_length(pair)=2 AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(pair->0->'ratings') WITH ORDINALITY x WHERE abs(x.value::text::numeric-(pair->1->'ratings'->>(x.ordinality-1)::integer)::numeric)>1) THEN SELECT avg((x.value::text::numeric-1)*25) INTO v FROM jsonb_array_elements(pair) r CROSS JOIN LATERAL jsonb_array_elements(r->'ratings') x;END IF;END IF;ELSIF method='sjt' THEN IF a.answers->>(i->>'id') ~ '^[1-5],[1-5],[1-5],[1-5]$' THEN SELECT (1-sum(abs(x.val::numeric-(i->'key'->>(x.n-1)::integer)::numeric))/16)*100 INTO v FROM unnest(string_to_array(a.answers->>(i->>'id'),',')) WITH ORDINALITY x(val,n);ELSE v:=0;END IF;ELSE v:=CASE WHEN a.answers->>(i->>'id') ~ '^\d+$' AND (a.answers->>(i->>'id'))::integer=(i->>'correct')::integer THEN 100 ELSE 0 END;END IF;IF v IS NOT NULL THEN itemsc:=itemsc||jsonb_build_object(i->>'id',v);END IF;END LOOP;
FOR method IN SELECT DISTINCT value->>'method' FROM jsonb_array_elements(b.payload->'items') WHERE value->>'status'='approved' AND NOT (value->>'practice')::boolean LOOP IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(b.payload->'items') WHERE value->>'method'=method AND value->>'status'='approved' AND NOT (value->>'practice')::boolean AND NOT itemsc ? (value->>'id')) THEN SELECT avg((itemsc->>(value->>'id'))::numeric) INTO v FROM jsonb_array_elements(b.payload->'items') WHERE value->>'method'=method AND value->>'status'='approved' AND NOT (value->>'practice')::boolean;sc:=sc||jsonb_build_object(method,v);END IF;END LOOP;
FOR key IN SELECT DISTINCT jsonb_array_elements_text(value->'ksao_ids') FROM jsonb_array_elements(b.payload->'items') WHERE value->>'status'='approved' AND NOT (value->>'practice')::boolean LOOP IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(b.payload->'items') WHERE value->'ksao_ids' ? key AND value->>'status'='approved' AND NOT (value->>'practice')::boolean AND NOT itemsc ? (value->>'id')) THEN SELECT avg((itemsc->>(value->>'id'))::numeric) INTO v FROM jsonb_array_elements(b.payload->'items') WHERE value->'ksao_ids' ? key AND value->>'status'='approved' AND NOT (value->>'practice')::boolean;ksc:=ksc||jsonb_build_object(key,v);END IF;END LOOP;
w:=b.payload->'weight_overrides';IF w IS NULL OR w='{}' THEN SELECT jsonb_object_agg(m,weight) INTO w FROM (SELECT m,sum(importance)::numeric/sum(sum(importance)) OVER()*100 weight FROM (SELECT jsonb_array_elements_text(mp->'methods') m,avg((r->>'importance')::numeric)/jsonb_array_length(mp->'methods') importance FROM jsonb_array_elements(b.payload->'mappings') mp JOIN LATERAL jsonb_array_elements(b.payload->'ratings') r ON r->>'element_id'=mp->>'element_id' WHERE (r->>'entry')::boolean AND (r->>'applies')::boolean GROUP BY mp) s GROUP BY m) t;END IF;
FOR method,weight IN SELECT k,value::text::numeric FROM jsonb_each(w) t(k,value) LOOP IF weight>0 THEN IF NOT sc ? method THEN done:=false;ELSE total:=total+(sc->>method)::numeric*weight/100;END IF;END IF;END LOOP;
DELETE FROM pipeline_scores WHERE attempt_id=aid;INSERT INTO pipeline_scores(attempt_id,score_type,score_key,value) SELECT aid,'item',key,value::text::numeric FROM jsonb_each(itemsc);INSERT INTO pipeline_scores(attempt_id,score_type,score_key,value) SELECT aid,'section',key,value::text::numeric FROM jsonb_each(sc);INSERT INTO pipeline_scores(attempt_id,score_type,score_key,value) SELECT aid,'ksao',key,value::text::numeric FROM jsonb_each(ksc);IF done THEN INSERT INTO pipeline_scores VALUES(aid,'composite','total',total,now());END IF;UPDATE assessment_attempts SET scores=sc,auto_scored_at=coalesce(auto_scored_at,now()),status=CASE WHEN done THEN 'scored' ELSE 'submitted' END WHERE id=aid;RETURN done;END $$;
REVOKE ALL ON FUNCTION pipeline_recalculate(uuid) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION pipeline_recalculate(uuid) TO service_role;
CREATE FUNCTION public.pipeline_rater_score(aid uuid,item text,ratings jsonb,comment text,consensus boolean DEFAULT false) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a assessment_attempts;i jsonb;rows jsonb;BEGIN PERFORM pg_advisory_xact_lock(811112026);SELECT * INTO a FROM assessment_attempts WHERE id=aid FOR UPDATE;IF NOT org_can('score',a.battery_id) OR a.status NOT IN ('submitted','scored') OR a.purged_at IS NOT NULL THEN RAISE EXCEPTION 'Assigned Rater required';END IF;SELECT value INTO i FROM assessment_batteries b CROSS JOIN LATERAL jsonb_array_elements(b.payload->'items') WHERE b.id=a.battery_id AND value->>'id'=item;IF i->>'method'<>'work_sample' OR jsonb_array_length(ratings)<>jsonb_array_length(i->'rubric') OR EXISTS(SELECT 1 FROM jsonb_array_elements(ratings) v WHERE v::text::numeric NOT BETWEEN 1 AND 5 OR v::text::numeric<>floor(v::text::numeric)) OR btrim(comment)='' THEN RAISE EXCEPTION 'Every rubric dimension and a comment are required';END IF;IF consensus THEN IF NOT org_can('people') THEN RAISE EXCEPTION 'Admin consensus record required';END IF;UPDATE assessment_attempts SET reconciliations=reconciliations||jsonb_build_object(item,jsonb_build_object('ratings',ratings,'note',comment)) WHERE id=aid;ELSE IF NOT EXISTS(SELECT 1 FROM assessment_rater_assignments r JOIN org_people p ON p.id=r.person_id WHERE r.attempt_id=aid AND r.item_id=item AND p.user_id=auth.uid()) AND NOT org_can('people') THEN RAISE EXCEPTION 'This work sample is not assigned to you';END IF;INSERT INTO pipeline_rater_scores(attempt_id,item_id,rater_id,ratings,comment) VALUES(aid,item,auth.uid(),ratings,comment) ON CONFLICT(attempt_id,item_id,rater_id) DO UPDATE SET ratings=excluded.ratings,comment=excluded.comment,created_at=now();SELECT coalesce(jsonb_agg(value),'[]') INTO rows FROM jsonb_array_elements(a.raters) WHERE value->>'item_id'<>item OR value->>'user_id'<>auth.uid()::text;UPDATE assessment_attempts SET raters=rows||jsonb_build_array(jsonb_build_object('item_id',item,'user_id',auth.uid(),'ratings',ratings,'note',comment)) WHERE id=aid;END IF;PERFORM pipeline_recalculate(aid);RETURN true;END $$;
CREATE FUNCTION public.pipeline_server_rater_score(aid uuid,item text,ratings jsonb,comment text,actor uuid,consensus boolean DEFAULT false) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.role()<>'service_role' THEN RAISE EXCEPTION 'Server action required';END IF;PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated')::text,true);PERFORM set_config('app.score_action',actor::text,true);RETURN pipeline_rater_score(aid,item,ratings,comment,consensus);END $$;
REVOKE ALL ON FUNCTION pipeline_rater_score(uuid,text,jsonb,text,boolean),pipeline_server_rater_score(uuid,text,jsonb,text,uuid,boolean) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION pipeline_server_rater_score(uuid,text,jsonb,text,uuid,boolean) TO service_role;